// n8n Code v2, Run Once for All Items. Native Crypto v2 supplies SHA256 hex.
// Binary content is read only through the documented helper, never metadata.data.
const items = $input.all();
const item = items[0];
if (!item?.binary?.baseline || !item?.binary?.actual) {
  throw new Error('HOLD: upload one baseline file and one actual file.');
}
const baseline = await this.helpers.getBinaryDataBuffer(0, 'baseline');
const actual = await this.helpers.getBinaryDataBuffer(0, 'actual');
const input = item.json || {};
const report = {
  mode: typeof input.mode === 'string' ? input.mode : '',
  result: 'HOLD', reason: '',
  baseline_name: item.binary.baseline.fileName || '',
  actual_name: item.binary.actual.fileName || '',
  baseline_size: baseline.length, actual_size: actual.length,
  baseline_sha256: typeof input.baseline_sha256 === 'string' ? input.baseline_sha256 : '',
  actual_sha256: typeof input.actual_sha256 === 'string' ? input.actual_sha256 : '',
  expected_sha256: typeof input.expected_sha256 === 'string' ? input.expected_sha256 : '',
  identity_check: 'not_requested',
  raw_byte_equal: baseline.equals(actual),
  baseline_row_count: null, actual_row_count: null,
  row_count_checked: 0, changed_ids: '[]', changed_count: 0, unchanged_count: 0,
};
const fail = (message) => { throw new Error(message); };
const same = (a, b) => a.length === b.length && a.every((value, i) => value === b[i]);
const validPair = (route, status) =>
  (route === 'pass' && status === 'READY') ||
  (route === 'hold' && ['OPEN', 'RESOURCE_CONFLICT'].includes(status)) ||
  (route === 'reject' && status === 'NOT_AUTHORIZED');

// Strict UTF-8 by lossless round-trip, retaining BOM, raw fields and each record's
// terminator separately. CSV quoting is parsed, never normalized for comparison.
function csv(buffer, columns, label) {
  const text = buffer.toString('utf8');
  if (!Buffer.from(text, 'utf8').equals(buffer)) fail(`${label}: invalid UTF-8.`);
  const bom = text.startsWith('\uFEFF') ? '\uFEFF' : '';
  let pos = bom.length;
  const records = [];
  while (pos < text.length) {
    const start = pos;
    const values = [];
    const tokens = [];
    let eol = '';
    while (true) {
      const fieldStart = pos;
      let value = '';
      if (text[pos] === '"') {
        pos++;
        let closed = false;
        while (pos < text.length) {
          if (text[pos] === '"') {
            if (text[pos + 1] === '"') { value += '"'; pos += 2; }
            else { pos++; closed = true; break; }
          } else value += text[pos++];
        }
        if (!closed) fail(`${label}: unclosed CSV quote.`);
        if (pos < text.length && ![',', '\r', '\n'].includes(text[pos])) fail(`${label}: text after closing CSV quote.`);
      } else {
        while (pos < text.length && ![',', '\r', '\n'].includes(text[pos])) {
          if (text[pos] === '"') fail(`${label}: quote inside an unquoted field.`);
          value += text[pos++];
        }
      }
      values.push(value);
      tokens.push(text.slice(fieldStart, pos));
      if (text[pos] === ',') { pos++; continue; }
      const end = pos;
      if (text[pos] === '\r') {
        if (text[pos + 1] !== '\n') fail(`${label}: bare CR is not a CSV record terminator.`);
        eol = '\r\n'; pos += 2;
      } else if (text[pos] === '\n') { eol = '\n'; pos++; }
      records.push({ values, tokens, raw: text.slice(start, end), eol });
      break;
    }
  }
  if (!records.length || !same(records[0].values, columns)) fail(`${label}: expected exactly ${columns.join(',')} in that order.`);
  const ids = new Set();
  for (const [i, record] of records.slice(1).entries()) {
    if (record.values.length !== columns.length) fail(`${label}: row ${i + 1} has the wrong number of fields.`);
    if (record.values.some(value => /[\x00-\x1f\x7f]/.test(value))) fail(`${label}: row ${i + 1} contains a control character.`);
    const id = record.values[0];
    if (!id.trim() || /[,"\r\n\0]/.test(id)) fail(`${label}: row ${i + 1} has an invalid lot.`);
    if (ids.has(id)) fail(`${label}: duplicate lot ${JSON.stringify(id)}.`);
    ids.add(id);
    for (let field = 1; field < columns.length; field += 2) {
      if (!validPair(record.values[field], record.values[field + 1])) fail(`${label}: row ${i + 1} has an invalid route/status pair.`);
    }
  }
  return { bom, header: records[0], rows: records.slice(1) };
}

try {
  if (items.length !== 1) fail('Provide exactly one comparison item.');
  if (!['exact', 'predicted-change', 'file-identity'].includes(input.mode)) fail('Choose exact, predicted-change, or file-identity mode.');
  for (const key of ['baseline_sha256', 'actual_sha256']) {
    if (typeof input[key] !== 'string' || !/^[a-fA-F0-9]{64}$/.test(input[key])) fail(`Missing or invalid ${key}; run the native SHA256 Crypto node.`);
    report[key] = input[key].toLowerCase();
  }
  if (report.raw_byte_equal && report.baseline_sha256 !== report.actual_sha256) fail('Equal files have inconsistent native hashes; check Crypto field selection.');
  const expected = input.expected_sha256;
  if (expected !== undefined && expected !== '') {
    if (typeof expected !== 'string' || !/^[a-fA-F0-9]{64}$/.test(expected)) fail('expected_sha256 must be the 64-digit hex digest from the retained original report.');
    report.expected_sha256 = expected.toLowerCase();
    report.identity_check = 'mismatch';
    if (report.baseline_sha256 !== report.expected_sha256 || report.actual_sha256 !== report.expected_sha256) fail('Files do not match the retained original expected_sha256.');
    report.identity_check = 'matched';
  }
  if (input.mode === 'file-identity') {
    if (!report.raw_byte_equal) fail('File identity requires byte-identical baseline and actual files.');
    if (report.identity_check === 'not_requested') report.identity_check = 'initial_record_only';
  } else {
    const columns = ['lot', 'route', 'status'];
    const before = csv(baseline, columns, 'baseline');
    const after = csv(actual, columns, 'actual');
    report.baseline_row_count = before.rows.length;
    report.actual_row_count = after.rows.length;
    let predictions = new Map();
    if (input.mode === 'predicted-change') {
      if (!item.binary.delta) fail('Upload a delta CSV; a header-only delta declares zero changes.');
      const deltaBuffer = await this.helpers.getBinaryDataBuffer(0, 'delta');
      const delta = csv(deltaBuffer, ['lot', 'before_route', 'before_status', 'after_route', 'after_status'], 'delta');
      predictions = new Map(delta.rows.map(row => [row.values[0], row.values]));
    }
    const problems = [];
    if (before.rows.length !== after.rows.length) problems.push('Receipt row counts differ (missing or extra rows).');
    if (before.bom !== after.bom || before.header.raw !== after.header.raw || before.header.eol !== after.header.eol) problems.push('Receipt header/BOM/framing changed.');
    const changed = [];
    const baselineIds = new Set(before.rows.map(row => row.values[0]));
    for (const id of predictions.keys()) if (!baselineIds.has(id)) problems.push(`Predicted lot ${JSON.stringify(id)} is absent from baseline.`);
    for (let i = 0; i < before.rows.length; i++) {
      const b = before.rows[i];
      const a = after.rows[i];
      if (!a) continue;
      report.row_count_checked++;
      const id = b.values[0];
      if (id !== a.values[0]) { problems.push(`Lot identity/order changed at row ${i + 1}.`); continue; }
      const differs = !same(b.values, a.values);
      if (differs) changed.push(id);
      else if (b.raw === a.raw && b.eol === a.eol) report.unchanged_count++;
      if (b.eol !== a.eol) problems.push(`Record terminator changed for ${JSON.stringify(id)}.`);
      const prediction = predictions.get(id);
      if (input.mode === 'predicted-change' && prediction) {
        if (!differs) problems.push(`Prediction for ${JSON.stringify(id)} is a no-op.`);
        if (!same(prediction.slice(1, 3), b.values.slice(1)) || !same(prediction.slice(3), a.values.slice(1))) problems.push(`Prediction before/after mismatch for ${JSON.stringify(id)}.`);
        if (b.tokens[0] !== a.tokens[0] || b.tokens.some((token, j) => token.startsWith('"') !== a.tokens[j].startsWith('"'))) problems.push(`CSV field framing changed for ${JSON.stringify(id)}.`);
      } else if (b.raw !== a.raw || b.eol !== a.eol) {
        problems.push(`Unpredicted serialized change for ${JSON.stringify(id)}.`);
      }
    }
    report.changed_ids = JSON.stringify(changed);
    report.changed_count = changed.length;
    if (input.mode === 'exact' && !report.raw_byte_equal) problems.push('Exact comparison requires complete raw-byte equality.');
    if (problems.length) fail(problems.join(' '));
  }
  report.result = 'PASS';
  report.reason = input.mode === 'file-identity' && report.identity_check === 'initial_record_only'
    ? 'Files are identical. Retain this initial digest report; future verification must supply its original expected_sha256.'
    : 'All comparison requirements satisfied.';
} catch (error) {
  report.reason = error instanceof Error ? error.message : String(error);
}
return [{ json: report, pairedItem: { item: 0 } }];
